"""决战阶段枚举与运行时状态。

v6 决战状态只跟踪“章节 / 小关 / 节点 / 点数 / 舰船 / 副官 / 技能”，
不再记录血量：血量由游戏引擎负责，撤退时也不回退。
"""

from __future__ import annotations

from dataclasses import dataclass, field

from autowsgr.types import DecisivePhase


@dataclass(frozen=True)
class StageSnapshot:
    """进入当前小关时的状态快照。

    撤退后把以下字段恢复到快照值；血量不在快照内。
    """

    stage: int
    score: int
    ship_levels: dict[str, int]
    instructor: str
    instructor_level: int
    skill_used_levels: frozenset[int]


@dataclass
class DecisiveState:
    """决战运行时可变状态。

    Attributes
    ----------
    chapter:
        章节 (1-6)。
    stage:
        当前小关 (1-3), 0 表示尚未开始。
    node:
        当前节点字母 ('A', 'B', ...)；``U`` 表示未知节点，不得推进。
    phase:
        当前宏观阶段。
    score:
        当前可用资源分数 (蜂蜜)。
    ship_levels:
        已获取舰船 → 强化计数（同名船 +1/+2）。
    fleet:
        当前编队舰船列表 (索引 0 留空, 1-6 为位置)。
    instructor:
        当前副官名。
    instructor_level:
        副官技能等级（章节级单值，跨小关继承，撤退回退）。
    skill_used_levels:
        本小关已用技能等级（如 ``{3}``）。
    refresh_count:
        本节点/小关的购买页刷新次数，防死循环。
    stage_enter_snapshot:
        进入当前小关时的状态快照；撤退后用于恢复。
    """

    chapter: int = 6
    stage: int = 0
    node: str = 'U'  # U 表示未知节点
    phase: DecisivePhase = DecisivePhase.INIT
    score: int = 10
    ship_levels: dict[str, int] = field(default_factory=dict)
    fleet: list[str] = field(default_factory=lambda: [''] * 7)
    instructor: str = ''
    instructor_level: int = 1
    skill_used_levels: set[int] = field(default_factory=set)
    refresh_count: int = 0
    stage_enter_snapshot: StageSnapshot | None = None

    def reset(self) -> None:
        """重置状态 (保留 chapter)。"""
        chapter = self.chapter
        self.__init__()  # type: ignore[misc]
        self.chapter = chapter

    def add_ship(self, name: str) -> None:
        """记录一艘舰船；同名船累加强化计数。"""
        if not name:
            return
        self.ship_levels[name] = self.ship_levels.get(name, 0) + 1

    def capture_stage_snapshot(self) -> StageSnapshot:
        """把当前状态记录为“进入本小关”的快照。"""
        snapshot = StageSnapshot(
            stage=self.stage,
            score=self.score,
            ship_levels=dict(self.ship_levels),
            instructor=self.instructor,
            instructor_level=self.instructor_level,
            skill_used_levels=frozenset(self.skill_used_levels),
        )
        self.stage_enter_snapshot = snapshot
        return snapshot

    def restore_stage_snapshot(self) -> bool:
        """撤退后恢复快照；血量/舰队部署不在此处恢复。

        Returns
        -------
        bool
            是否存在可用快照并完成恢复。
        """
        snapshot = self.stage_enter_snapshot
        if snapshot is None:
            return False
        self.stage = snapshot.stage
        self.score = snapshot.score
        self.ship_levels = dict(snapshot.ship_levels)
        self.instructor = snapshot.instructor
        self.instructor_level = snapshot.instructor_level
        self.skill_used_levels = set(snapshot.skill_used_levels)
        self.node = 'A'
        self.refresh_count = 0
        self.fleet = [''] * 7
        return True

    def begin_new_stage(self) -> None:
        """小关通关后清空小关局部状态，保留跨小关继承值。"""
        self.node = 'A'
        self.refresh_count = 0
        self.skill_used_levels.clear()
        self.stage_enter_snapshot = None

    def is_begin(self) -> bool:
        """是否在第一小关第一节点。"""
        # 如果在第一关且是未知节点，仍返回True，以防不选船导致无法推进
        return self.stage <= 1 and self.node in {'A', 'U'}
